effect.shader:
void main() {
    vec4 orig = texture(inputImg, acScreenNorm);
    vec2 p = acScreenNorm - source;
    p.x *= acAspect;
    float r = length(p);
    float ang = atan(p.y, p.x) + acTime * spin;
    float faixa = 0.5 + 0.5 * cos(ang * float(int(count)));
    float queda = exp(-r * falloff * 2.0);
    float raio = faixa * queda;
    vec3 cor = orig.rgb + tint.rgb * tint.a * raio * intensity;
    fragColor = vec4(cor, orig.a);
}
